public:
    // Authored cLinkedList<cRBod>::Add(cRBod&); the reference has the same
    // pointer ABI as this Windows projection.
    void add_bod_to_front(BodNode* node); // @ 0x4113b0
    // Exact tail splice inlined by cRGame::Init4 on Android/iOS. The mobile
    // binaries preserve List ADDend but do not export a method name for it.
    void append_bod_to_end(BodNode* node); // @ 0x411420
    void recycle_bod_to_free_list(BodNode* node); // @ 0x447290

    // Inlined cLinkedList<cRBod>::Add used by pickup allocators.
    void add_bod_reference(BodNode& node)
    {
        if ((node.list_flags & BOD_FLAG_LINKED) != 0) {
            report_errorf("List ADD");
        } else {
            if (first == 0) {
                first = &node;
                node.list_prev = 0;
                first->list_next = 0;
            } else {
                first->list_prev = &node;
                first->list_prev->list_next = first;
                first = first->list_prev;
                first->list_prev = 0;
            }
            node.list_flags |= BOD_FLAG_LINKED;
        }
    }

    void add_bod(BodNode* node)
    {
        add_bod_reference(*node);
    }

    // Inlined cLinkedList<cRBod>::Remove; 0x447290 is its exact emitted copy.
    void remove_bod(BodNode* node)
    {
        if ((node->list_flags & BOD_FLAG_LINKED) == 0) {
            report_errorf("List remove");
            return;
        }
        unsigned int next_update = node->list_flags & BOD_FLAG_NEXT_UPDATE_GUARD;
        if (next_update != 0) {
            report_errorf("List remove NEXTBOD");
            return;
        }

        BodNode* next = node->list_next;
        if (next != 0)
            next->list_prev = node->list_prev;

        BodNode* prev = node->list_prev;
        if (prev != 0)
            prev->list_next = node->list_next;
        else
            first = node->list_next;

        node->list_next = free_top;
        free_top = node;
        node->list_flags &= ~BOD_FLAG_LINKED;
    }

